scwin.trigger1_onclick = function(e) {
    //dataList1.sort('col1', 0);
    var options = {};
    options.sortIndex = "col1";
    options.sortOrder = "1";
    options.type = "sort";
    gridView1.dataList.setFilter(options);
}
scwin.trigger2_onclick = function(e) {
    var options = {};
    options.sortIndex = "col1 col2";
    options.sortOrder = "1 1";
    options.type = "sort";
    //dataList1.multisort(options);
    gridView1.dataList.setFilter(options);
};

scwin.trigger3_onclick = function(e) {
    dataList2.sort('col1', 0);
};

scwin.trigger4_onclick = function(e) {
    var options = {};
    options.sortIndex = "col1 col2";
    options.sortOrder = "1 1";

    dataList2.multisort(options);
};

	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('gridView1_cell_0_0').innerText == '건물';
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
		WebSquare.wUnit.addCommand("pause", "400");			

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
